import { EllipsisVertical } from 'lucide-react'
import { Fragment, type ReactNode } from 'react'
import { Button } from '@/components/atoms/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  type DropdownMenuItemVariant,
  DropdownMenuTrigger
} from '@/components/atoms/dropdown-menu'

export interface BaseMenu {
  icon?: ReactNode
  id: string
  label?: ReactNode
  variant?: DropdownMenuItemVariant
}

export interface LinkMenu extends BaseMenu {
  link: string
  type: 'link'
}

export interface EventMenu extends BaseMenu {
  onClick: () => void
  type: 'event'
}

export interface SlotMenu extends BaseMenu {
  slot: ReactNode
  type: 'slot'
}

export type Menu = LinkMenu | EventMenu | SlotMenu

export function DataTableActionCell({ menus, loading }: { menus: Menu[]; loading?: boolean }) {
  if (!menus.length) {
    return null
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button loading={loading} size='icon' variant='ghost'>
            <EllipsisVertical className='size-4' />
          </Button>
        }
      />

      <DropdownMenuContent>
        {menus.map((menu) => {
          switch (menu.type) {
            case 'link':
              return (
                <DropdownMenuItem
                  key={menu.id}
                  render={
                    <a href={menu.link}>
                      {menu.icon}
                      {menu.label}
                    </a>
                  }
                />
              )

            case 'event':
              return (
                <DropdownMenuItem key={menu.id} onClick={menu.onClick} variant={menu.variant}>
                  {menu.icon}
                  {menu.label}
                </DropdownMenuItem>
              )

            case 'slot':
              return <Fragment key={menu.id}>{menu.slot}</Fragment>

            default:
              return null
          }
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

import type { RowData } from '@tanstack/react-table'
import type { DataTableProps } from './data-table'

export default function DataTableAdditionalInfo<TData extends RowData>({
  table,
  loading,
  error
}: Pick<DataTableProps<TData>, 'table' | 'error' | 'loading'>) {
  const rowLength = table.getRowModel().rows.length
  const empty = !(rowLength || loading)

  if (error) {
    return <div className='flex items-center justify-center p-4'>An error occurred, please reload the page</div>
  }

  if (empty) {
    return <div className='flex items-center justify-center p-4'>No data available</div>
  }

  return null
}

import { flexRender, type RowData } from '@tanstack/react-table'
import React from 'react'
import { TableBody, TableCell, TableRow } from '@/components/atoms/table'
import { cn } from '@/utils/ui'
import type { DataTableProps } from './data-table'
import { getCommonPinningStyles } from './lib'

export default function DataTableBody<TData extends RowData>({
  table,
  className,
  onRenderSubComponent,
  onRenderAdditionalRow
}: Pick<DataTableProps<TData>, 'table' | 'onRenderSubComponent' | 'onRenderAdditionalRow'> & {
  className?: string
}) {
  const { rows } = table.getRowModel()

  return (
    <TableBody className={cn('relative', className)}>
      {rows.map((row) => {
        const isExpanded = row.getIsExpanded()
        const rowClassName: string =
          (typeof row.original === 'object' && row.original && 'className' in row.original
            ? (row.original.className as string)
            : '') ?? ''

        return (
          <React.Fragment key={row.id}>
            <TableRow
              className={cn('[&:not(:last-child)_td]:border-b', isExpanded && 'border-b-0', rowClassName)}
              data-state={row.getIsSelected() && 'selected'}
            >
              {row.getVisibleCells().map((cell) => (
                <TableCell key={cell.id} style={{ ...getCommonPinningStyles(cell.column) }}>
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </TableCell>
              ))}
            </TableRow>

            {/* Sub component */}
            {onRenderSubComponent && (
              <TableRow
                className={cn('hidden', {
                  'table-row': isExpanded
                })}
              >
                <TableCell colSpan={row.getVisibleCells().length}>{onRenderSubComponent(row)}</TableCell>
              </TableRow>
            )}
          </React.Fragment>
        )
      })}

      {onRenderAdditionalRow && (
        <TableRow>
          <TableCell colSpan={table.getAllFlatColumns().length}>{onRenderAdditionalRow(table)}</TableCell>
        </TableRow>
      )}
    </TableBody>
  )
}

import type { CellContext, RowData } from '@tanstack/react-table'
import { Checkbox } from '@/components/atoms/checkbox'

export function DataTableCheckboxCell<TData extends RowData>({ table, row }: CellContext<TData, unknown>) {
  return (
    <div className='flex h-full items-center justify-center'>
      <Checkbox
        checked={row.getIsSelected()}
        onCheckedChange={(value) => {
          row.toggleSelected(value as boolean)
          table?.options.meta?.setIsSelectAllRows?.(false)
        }}
      />
    </div>
  )
}

import type { HeaderContext, RowData } from '@tanstack/react-table'
import { Checkbox } from '@/components/atoms/checkbox'

export function DataTableCheckboxHeader<TData extends RowData>({ table }: HeaderContext<TData, unknown>) {
  return (
    <div className='flex h-full w-full items-center justify-center'>
      <Checkbox
        checked={table.getIsAllPageRowsSelected()}
        indeterminate={table.getIsSomePageRowsSelected()}
        onCheckedChange={(value) => {
          table.toggleAllPageRowsSelected(!!value)
          table.options.meta?.setIsSelectAllRows?.(false)
        }}
      />
    </div>
  )
}

import type { Column, RowData, Table, VisibilityState } from '@tanstack/react-table'
import { ChevronDownIcon } from 'lucide-react'
import { useState } from 'react'
import { Button } from '@/components/atoms/button'
import { Checkbox } from '@/components/atoms/checkbox'
import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
  ComboboxTrigger
} from '@/components/atoms/combobox'
import { InputGroupAddon } from '@/components/atoms/input-group'

export function DataTableColumnVisibilitySelect<TData extends RowData>({ table }: { table: Table<TData> }) {
  const [columns] = useState(() =>
    table
      .getAllLeafColumns()
      .filter((column) => column.id && column.getCanHide() && typeof column.columnDef.header === 'string')
  )

  const { columnVisibility } = table.getState()
  const visibleColumns = columns.filter((column) => columnVisibility[column.id] ?? true)

  const allColumnsVisible = table.getIsAllColumnsVisible()
  const someColumnsVisible = table.getIsSomeColumnsVisible()

  return (
    <Combobox
      items={columns}
      multiple
      onValueChange={(value) => {
        table.setColumnVisibility(() => {
          const newColumnVisibility = columns.reduce<VisibilityState>((acc, column) => {
            acc[column.id] = false
            return acc
          }, {})

          for (const column of value) {
            newColumnVisibility[column.id] = true
          }

          return newColumnVisibility
        })
      }}
      value={visibleColumns}
    >
      <ComboboxTrigger
        render={
          <Button className='w-64 justify-between font-normal' variant='outline'>
            <span>Columns</span>
            <ChevronDownIcon className='text-muted-foreground' />
          </Button>
        }
      />
      <ComboboxContent>
        <ComboboxInput placeholder='Search' showTrigger={false}>
          <InputGroupAddon
            align='inline-start'
            onClick={(e) => {
              e.stopPropagation()
            }}
          >
            <Checkbox
              checked={allColumnsVisible}
              className='cursor-default'
              indeterminate={!allColumnsVisible && someColumnsVisible}
              onCheckedChange={(checked) => {
                table.toggleAllColumnsVisible(checked)
              }}
            />
          </InputGroupAddon>
        </ComboboxInput>

        <ComboboxEmpty>No columns found.</ComboboxEmpty>
        <ComboboxList>
          {(column: Column<TData, unknown>) => (
            <ComboboxItem key={column.id} value={column}>
              {column.columnDef.header as string}
            </ComboboxItem>
          )}
        </ComboboxList>
      </ComboboxContent>
    </Combobox>
  )
}

import { flexRender, type RowData } from '@tanstack/react-table'
import { TableCell, TableFooter, TableRow } from '@/components/atoms/table'
import type { DataTableProps } from './data-table'

export default function DataTableFooter<TData extends RowData>({
  table,
  className
}: Pick<DataTableProps<TData>, 'table'> & {
  className?: string
}) {
  return (
    <TableFooter className={className}>
      {table.getFooterGroups().map((footerGroup) => (
        <TableRow key={footerGroup.id}>
          {footerGroup.headers.map((header) => (
            <TableCell colSpan={header.colSpan} key={header.id}>
              {header.isPlaceholder ? null : flexRender(header.column.columnDef.footer, header.getContext())}
            </TableCell>
          ))}
        </TableRow>
      ))}
    </TableFooter>
  )
}

import { flexRender, type RowData } from '@tanstack/react-table'
import { ChevronLeftIcon, ChevronRightIcon, PinOffIcon } from 'lucide-react'
import { Button } from '@/components/atoms/button'
import { TableHead, TableHeader, TableRow } from '@/components/atoms/table'
import { cn } from '@/utils/ui'
import type { DataTableProps } from './data-table'
import { getCommonPinningStyles } from './lib'

export default function DataTableHeader<TData extends RowData>({
  table,
  className
}: Pick<DataTableProps<TData>, 'table'> & { className?: string }) {
  return (
    <TableHeader className={cn('sticky top-0 z-20', className)}>
      {table.getHeaderGroups().map((headerGroup) => (
        <TableRow className='bg-background hover:bg-background' key={headerGroup.id}>
          {headerGroup.headers.map((header, headerIndex) => {
            const pinningPosition = header.column.getIsPinned()

            const columnRelativeDepth = header.depth - header.column.depth
            if (columnRelativeDepth > 1) {
              return null
            }

            let rowSpan = 1
            if (header.isPlaceholder) {
              const leafs = header.getLeafHeaders()
              const lastLeftDepth = leafs.at(-1)?.depth
              if (lastLeftDepth) {
                rowSpan = lastLeftDepth - header.depth
              }
            }

            return (
              <TableHead
                className={cn('space-y-1 border-b border-l', header.column.columnDef.meta?.className, {
                  'first:border-l-0': headerIndex === 0
                })}
                colSpan={header.colSpan}
                key={header.id}
                rowSpan={rowSpan}
                style={{
                  ...getCommonPinningStyles(header.column)
                }}
              >
                <div className='whitespace-nowrap'>
                  {flexRender(header.column.columnDef.header, header.getContext())}
                </div>

                {header.column.getCanPin() && (
                  <div className='flex gap-2'>
                    {pinningPosition !== 'left' && (
                      <Button
                        onClick={() => {
                          header.column.pin('left')
                        }}
                        size='icon-xs'
                        variant='outline'
                      >
                        <ChevronLeftIcon />
                      </Button>
                    )}

                    {pinningPosition && (
                      <Button
                        onClick={() => {
                          header.column.pin(false)
                        }}
                        size='icon-xs'
                        variant='outline'
                      >
                        <PinOffIcon />
                      </Button>
                    )}

                    {pinningPosition !== 'right' && (
                      <Button
                        onClick={() => {
                          header.column.pin('right')
                        }}
                        size='icon-xs'
                        variant='outline'
                      >
                        <ChevronRightIcon />
                      </Button>
                    )}
                  </div>
                )}
              </TableHead>
            )
          })}
        </TableRow>
      ))}
    </TableHeader>
  )
}

import type { RowData } from '@tanstack/react-table'
import debounce from 'lodash.debounce'
import type { NumberFormatValues } from 'react-number-format'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/atoms/select'
import { NumberInput } from '@/components/molecules/number-input'
import { Pagination } from '@/components/molecules/pagination'
import { cn } from '@/utils/ui'
import type { DataTableProps } from './data-table'

const pageSizeOptions = [10, 20, 30, 50, 100]

export default function DataTablePagination<TData extends RowData>({
  table,
  className
}: Pick<DataTableProps<TData>, 'table'> & {
  className?: string
}) {
  const {
    pagination: { pageIndex, pageSize }
  } = table.getState()
  const page = pageIndex + 1
  const pageCount = table.getPageCount()

  const changeNumberInputValue = debounce((values: NumberFormatValues) => {
    if (values.floatValue === undefined || values.floatValue < 1) {
      return
    }
    if (values.floatValue > pageCount) {
      return table.setPageIndex(pageCount - 1)
    }
    return table.setPageIndex(values.floatValue - 1)
  }, 400)

  return (
    <div
      className={cn(
        'flex w-full flex-col items-center justify-between gap-4 border-t bg-muted/50 p-4 text-sm xl:flex-row',
        className
      )}
    >
      {/* Page input & page size */}
      <div className='flex flex-col items-center gap-4 xl:flex-row'>
        {/* Page input */}
        <div className='flex items-center gap-2'>
          <span>Move to page</span>
          <NumberInput
            className='w-14'
            defaultValue={page}
            isDisplayStepper={false}
            max={pageCount}
            min={1}
            onValueChange={changeNumberInputValue}
            placeholder=''
          />
        </div>

        {/* Page size selection */}
        <div className='flex items-center gap-2'>
          <span>Number of rows per page</span>
          <Select
            onValueChange={(value) => {
              table.setPageSize(Number(value))
            }}
            value={`${pageSize}`}
          >
            <SelectTrigger className='w-fit gap-1'>
              <SelectValue />
            </SelectTrigger>
            <SelectContent side='top'>
              {pageSizeOptions.map((pageSize) => (
                <SelectItem key={pageSize} value={`${pageSize}`}>
                  {pageSize}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <Pagination
        isHasNextPage={table.getCanNextPage()}
        isHasPreviousPage={table.getCanPreviousPage()}
        onChangePage={(page) => table.setPageIndex(page - 1)}
        onGoToNextPage={table.nextPage}
        onGoToPreviousPage={table.previousPage}
        page={page}
        pageCount={pageCount}
      />
    </div>
  )
}

import type { RowData } from '@tanstack/react-table'
import { ListChecksIcon } from 'lucide-react'
import { Button } from '@/components/atoms/button'
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/atoms/tooltip'
import { cn } from '@/utils/ui'
import type { DataTableProps } from './data-table'

export default function DataTableRowSelection<TData extends RowData>({ table }: Pick<DataTableProps<TData>, 'table'>) {
  const rowCount = table.getRowCount()
  const rowSelectionLength = Object.keys(table.getState().rowSelection).length
  const pageRowCount = table.getPreFilteredRowModel().rows.length
  const { isSelectAllRows, setIsSelectAllRows } = table.options.meta ?? {}

  const toggleSelectAllRows = () => {
    setIsSelectAllRows?.((prev) => !prev)
    table.toggleAllPageRowsSelected(!isSelectAllRows)
  }

  if (!rowSelectionLength) {
    return null
  }

  return (
    <div
      className={cn('w-full animate-in bg-muted/50 p-4 text-sm', {
        'fade-in slide-in-from-top-60': rowSelectionLength > 0
      })}
    >
      <span>
        {isSelectAllRows ? `All ${rowCount} rows selected` : `${rowSelectionLength}/${pageRowCount} rows selected`}
      </span>

      {pageRowCount < rowCount && (
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger
              render={
                <Button onClick={toggleSelectAllRows} size='icon-sm' variant='outline'>
                  <ListChecksIcon />
                </Button>
              }
            />
            <TooltipContent>
              {isSelectAllRows ? `Unselect all ${rowCount} rows` : `Select all ${rowCount} rows`}
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
      )}
    </div>
  )
}

import type { Table as ReactTable, Row, RowData } from '@tanstack/react-table'
import type { ReactNode } from 'react'
import { Table } from '@/components/atoms/table'
import { LoadingOverlay } from '@/components/molecules/loading-overlay'
import { cn } from '@/utils/ui'
import DataTableAdditionalInfo from './data-table-additional-info'
import DataTableBody from './data-table-body'
import DataTableFooter from './data-table-footer'
import DataTableHeader from './data-table-header'
import DataTablePagination from './data-table-pagination'
import DataTableRowSelect from './data-table-row-select'

export interface DataTableProps<TData extends RowData> {
  className?: {
    container?: string
    table?: string
    tableHeader?: string
    tableBody?: string
    tableFooter?: string
    tablePagination?: string
  }
  error?: boolean
  id?: string
  loading?: boolean
  onRenderAdditionalRow?: (table: ReactTable<TData>) => ReactNode
  onRenderSubComponent?: (row: Row<TData>) => ReactNode
  showFooter?: boolean
  showPagination?: boolean
  table: ReactTable<TData>
}

export function DataTable<TData extends RowData>({
  id,
  table,
  loading = false,
  error = false,
  showFooter = false,
  showPagination = true,
  className,
  onRenderSubComponent,
  onRenderAdditionalRow
}: DataTableProps<TData>) {
  return (
    <div
      className={cn(
        'flex max-h-[calc(100dvh-2rem)] w-full flex-col overflow-hidden rounded-md border',
        className?.container
      )}
      id={id}
    >
      <Table className={className?.table}>
        {/* Table header */}
        <DataTableHeader className={className?.tableHeader} table={table} />

        {/* Table body */}
        <DataTableBody
          className={className?.tableBody}
          onRenderAdditionalRow={onRenderAdditionalRow}
          onRenderSubComponent={onRenderSubComponent}
          table={table}
        />

        {/* Table footer */}
        {showFooter && <DataTableFooter className={className?.tableFooter} table={table} />}
      </Table>

      {/* Additional info */}
      <DataTableAdditionalInfo error={error} loading={loading} table={table} />

      {/* Row select */}
      <DataTableRowSelect table={table} />

      {/* Pagination */}
      {showPagination && <DataTablePagination className={className?.tablePagination} table={table} />}

      {/* Loading overlay */}
      <LoadingOverlay loading={loading} />
    </div>
  )
}

import { type Column, getCoreRowModel, type RowData, type TableOptions, useReactTable } from '@tanstack/react-table'

// Use data table
export function useDataTable<TData extends RowData>({
  enableColumnPinning = false,
  ...options
}: Omit<TableOptions<TData>, 'getCoreRowModel'>) {
  return useReactTable<TData>({
    enableColumnPinning,
    getRowId: (row: TData, index: number) =>
      typeof row === 'object' && row && 'id' in row ? String(row.id) : String(index),
    ...options,
    getCoreRowModel: getCoreRowModel()
  })
}

// Get common pinning styles
function getBoxShadow({
  isLastLeftPinnedColumn,
  isFirstRightPinnedColumn
}: {
  isLastLeftPinnedColumn: boolean
  isFirstRightPinnedColumn: boolean
}) {
  if (isLastLeftPinnedColumn) {
    return '-2px 0 2px -2px gray inset'
  }
  if (isFirstRightPinnedColumn) {
    return '2px 0 2px -2px gray inset'
  }
}

export function getCommonPinningStyles<TData extends RowData>(column: Column<TData>): React.CSSProperties {
  const pinningPosition = column.getIsPinned()
  const isLastLeftPinnedColumn = pinningPosition === 'left' && column.getIsLastColumn('left')
  const isFirstRightPinnedColumn = pinningPosition === 'right' && column.getIsFirstColumn('right')

  return {
    boxShadow: getBoxShadow({ isFirstRightPinnedColumn, isLastLeftPinnedColumn }),
    left: pinningPosition === 'left' ? `${column.getStart('left')}px` : undefined,
    minWidth: column.getSize(),
    position: pinningPosition ? 'sticky' : 'relative',
    right: pinningPosition === 'right' ? `${column.getAfter('right')}px` : undefined,
    zIndex: pinningPosition ? 1 : 0
  }
}

// Get number order
export function getNumberOrder(rowIndex: number, page: number, pageSize: number): number {
  return rowIndex + 1 + (page - 1) * pageSize
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

// Utils
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import type { Dispatch, SetStateAction } from 'react'

declare module '@tanstack/react-table' {
  // @ts-expect-error
  interface TableMeta {
    isSelectAllRows?: boolean
    setIsSelectAllRows?: Dispatch<SetStateAction<boolean>>
  }

  // @ts-expect-error
  interface ColumnMeta {
    className?: string
  }
}
